WITH with_last AS (SELECT s.*, top1.txn_type, top1.transaction_txn_time FROM accounts s LEFT JOIN LATERAL (SELECT c.txn_type, c.txn_time AS transaction_txn_time FROM transactions c WHERE c.account_id = s.id ORDER BY c.amount DESC, c.id DESC LIMIT 1) top1 ON TRUE) SELECT customer_id, DATE_TRUNC('YEAR', transaction_txn_time) AS year_start, ROUND(SUM(balance) / NULLIF(COUNT(CASE WHEN account_type = 'CREDIT' THEN 1 END), 0), 2) AS balance_per_credit, APPROX_PERCENTILE(balance, ARRAY(0.25, 0.5, 0.75)) AS balance_quartiles FROM with_last GROUP BY GROUPING SETS ((customer_id, DATE_TRUNC('YEAR', transaction_txn_time)), (customer_id), ()) ORDER BY customer_id DESC NULLS FIRST;
